//! Port of the owner's MIT-licensed `portable-digital-ice` package,
//! specifically `src/portable_digital_ice/{x3a,profile,reconstruction,dither,rng,output}.py`,
//! -- the classical (non-ML) IR-based dust/scratch defect repair pipeline,
//! "Legacy ICE": the 16-bit logarithmic response-LUT conversion, the
//! IR/RGB auxiliary-signal derivation, the continuous per-pixel defect
//! score, whole-frame defect-map assembly with neighborhood-based noise
//! confirmation (plan 16-01), the multiscale local-reconstruction
//! candidate generation, band combination, conditional dither, and
//! 16-bit output-LUT emission tying it all into `heal`/`repair_frame`
//! (plan 16-02). `heal`/`repair_frame` are this file's final public
//! entry points -- nothing in this module remains stubbed.
//!
//! Already MIT-licensed, same owner as this repository (see the source's
//! own `LICENSE` file) -- see `ICE-PROVENANCE.md` for the citation.
//!
//! REDUCED SCOPE, DOCUMENTED (see plan 16-01's `<scope_map>` and
//! `<single_acquisition_adaptation>`): this port implements the classical
//! IR-differential detection algorithm operating on a SINGLE main-scan RGBI
//! acquisition. It does NOT reproduce the real package's byte-exact
//! Nikon-firmware calibration replay, which HARD-REQUIRES a second, low-res
//! "prepass" acquisition (`portable_digital_ice.contracts.DualRGBIAcquisition`
//! rejects any job missing one) that this project's six-slot parity corpus
//! does not have (`engine/src/parity/corpus.rs`'s `CorpusSlot` has only
//! `rgb_path`/`ir_path` -- no prepass file). Every real parameter that would
//! normally come from reducing that prepass capture
//! (`profile.py`'s `LS5000Selector8NormalProfile.score_parameters`/
//! `auxiliary_parameters`/`reconstruction_parameters`) reduces to exactly
//! ONE frame-dependent scalar, `base_primary` (see
//! `IceParameters::for_main_scan`'s own doc comment) -- every other field
//! is a FIXED constant transcribed directly from the real profile. This
//! port also does NOT reproduce the real package's row-streaming/
//! hidden-startup-row replay architecture (a hardware line-buffer
//! memory-constraint replication this whole-frame in-memory engine does
//! not need -- `processing::nikonlook`/`processing::geometry` never
//! streamed either). Gated by this project's own parity harness
//! (mask-agreement Jaccard, deliberately generous -- see
//! `app/ScanStudio/PARITY.md`'s `ICE_MASK_AGREEMENT_THRESHOLD = 0.85`), not
//! a byte-exact claim against the real package's own "byte-identical to
//! Nikon" validation.
//!
//! Every numeric literal in this module's test suite (Groups L, A, P, D, N,
//! C, W, B, F, X, E) was generated by directly invoking the real, installed
//! `portable_digital_ice` package (`generate_nikon_response_lut`,
//! `SharedLookupInputResponse.nikon_logarithmic().convert`,
//! `derive_auxiliary`, `continuous_score`, `recovered_spatial_averages`,
//! `recovered_multiscale_candidates`, `recovered_weight_and_auxiliary_records_for_interior_row`,
//! `recovered_rgb_candidates`, `combine_recovered_candidate`,
//! `driver_forces_fallback`, `write_reconstructed_pixel`, `LCG24`,
//! `conditional_dither_delta`, `DitherBounds.from_lookup`,
//! `InverseResponseFactors.recovered_16bit`, `emit_public_rgb16`) against
//! synthetic input built from `tests/conftest.py`'s own `synthetic_rgbi`
//! recipe or this port's own extensions of that same recipe -- a faithful
//! numeric port of a verified reference implementation for the ported
//! math, not a reimplementation from first principles. Group R (`heal`/
//! `repair_frame` end-to-end) is the one exception: it verifies internal
//! ASSEMBLY correctness (clean-pixel passthrough, repair_frame's wrapper
//! behavior, no-panic on degenerate input) structurally rather than
//! against a live end-to-end Python invocation, since the real package's
//! own end-to-end pipelines (`startup.py`/`streaming.py`) require the dual
//! prepass+main acquisition and row-streaming architecture this
//! single-acquisition, whole-frame port does not reproduce (plan 16-01's
//! `<single_acquisition_adaptation>`) -- every INDIVIDUAL stage `heal`
//! assembles (candidate generation, band combination, write, dither,
//! output-LUT) is already ground-truth-verified in isolation by its own
//! group above.
//!
//! Two dead-code findings, both confirmed via direct grep across the
//! entire real source tree and documented in detail at their own
//! definitions: `pad_reconstruction_history` (reconstruction.py) and
//! `recovered_multiscale_candidates`/`combine_multiscale_bands`/
//! `dead_zone_residual`/`select_feature_band_extrema`/
//! `reconstruction_dither_draws` have zero real callers outside their own
//! definitions (`select_feature_band_extrema`/`pad_reconstruction_history`/
//! `reconstruction_dither_draws` are skipped entirely; the others are
//! ported and tested per this plan's own explicit request but are not on
//! `heal`'s own call path -- see each one's own doc comment for the exact
//! evidence). The whole-frame neighborhood-CONFIRMATION step
//! (`is_confirmed`) has no real-package equivalent to verify against: the
//! real functions are row-history/streaming-shaped and, verified
//! empirically during plan 16-01's execution, cannot by themselves
//! distinguish an isolated single-pixel noise spike from a genuine small
//! defect at any `perpendicular_radius`. See
//! `is_confirmed`'s own doc comment for the full adaptation rationale,
//! including the concrete numeric case that ruled out a literal reuse of
//! the real `sample_threshold` constant.

// ---------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------

/// Raw scanner RGBI counts (u16, NOT pre-normalized to `[0,1]` -- unlike
/// `processing::nikonlook`/`processing::geometry`'s `[0,1]`-normalized
/// float inputs, this port's response-LUT conversion operates on raw u16
/// counts directly, matching `portable_digital_ice.contracts.RGBI16Frame`'s
/// own raw-count convention). Row-major, one sample per pixel, matching
/// `parity::image_io::Rgb16Image`/`Gray16Image`'s own pixel convention
/// (`[R, G, B]` order for `rgb`).
#[derive(Debug, Clone, PartialEq)]
pub struct IceInputFrame {
    pub width: u32,
    pub height: u32,
    pub rgb: Vec<[u16; 3]>,
    pub ir: Vec<u16>,
}

/// Runtime parameters for the LS-5000/selector-8/Normal profile, adapted
/// for single-acquisition input (see `for_main_scan` and plan 16-01's
/// `<single_acquisition_adaptation>`). Every field except `base_primary`/
/// `coarse_reference` is a FIXED constant transcribed verbatim from
/// `portable_digital_ice.profile.LS5000Selector8NormalProfile` (see plan
/// 16-01's `<ice_parameters_table>`) -- cross-checked against the real
/// package's own `_f32_from_bits`-decoded values during this plan's
/// execution, not re-derived by hand.
#[derive(Debug, Clone)]
pub struct IceParameters {
    // score fields (profile.py's score_parameters())
    pub base_primary: f32,
    pub base_addend: f32,
    pub scale: f32,
    pub offset: f32,
    pub floor: f32,
    pub resolution_metric: u32,
    pub horizontal_minimum_resolution_cutoff: u32,
    // decision fields (profile.py's decision_parameters())
    pub sample_threshold: f32,
    pub count_limit: u32,
    pub perpendicular_radius: u32,
    // reconstruction fields (profile.py's reconstruction_parameters();
    // consumed by plan 16-02, defined here since IceParameters is this
    // plan's type, not 16-02's, per interface-first ordering)
    pub cross_neighbor_cutoff: u32,
    pub coarse_enabled: bool,
    pub coarse_reference: f32,
    pub coarse_slopes: [f32; 3],
    pub band_enabled: [bool; 3],
    pub band_scales: [f32; 3],
    pub factors_a: [[f32; 3]; 3],
    pub factors_b: [[f32; 3]; 3],
    pub configured_strengths: [f32; 3],
    pub driver_gate_primary: bool,
    pub driver_gate_secondary: bool,
    pub row_reconstruction_gate: u32,
    pub dither_scales: [f32; 3],
}

/// `portable_digital_ice.prepass.PrepassParameters
/// .captured_ls5000_selector8().zero_denominator_alpha`, narrowed to f32
/// then widened back to f64 (matching the real source's own
/// `float(np.float32(0.17))` construction) -- the single-acquisition
/// substitute alpha shared by `IceParameters::for_main_scan`'s
/// `base_primary` computation and `derive_auxiliary_plane` (see both their
/// doc comments for the full rationale). Not a fabricated number: it is
/// the real algorithm's own documented fallback for "no usable prepass
/// regression signal".
const SUBSTITUTE_ALPHA: f64 = 0.17f32 as f64;

impl IceParameters {
    /// Single-acquisition-adapted parameter set: transcribes every FIXED
    /// constant from `LS5000Selector8NormalProfile` (see plan 16-01's
    /// `<ice_parameters_table>`) and computes `base_primary`/
    /// `coarse_reference` directly from `frame`'s own robust (rail-excluded)
    /// mean response-converted R and IR statistics -- NOT from a real
    /// prepass capture (this project's six-slot parity corpus has none; see
    /// plan 16-01's `<single_acquisition_adaptation>` for the full
    /// rationale).
    ///
    /// **This is a documented fidelity reduction, not a byte-exact
    /// reproduction of Nikon's firmware prepass-register replay.** The real
    /// `profile.py`'s `_base_primary(record)` computes
    /// `(mean_ir - alpha * mean_r) / (1 - alpha)` from a real prepass
    /// capture's reduced calibration accumulators, where `alpha` is a
    /// per-frame regression result computed by
    /// `prepass.reduce_prepass_frame` (or, when that regression's
    /// denominator is exactly zero, the algorithm's OWN documented
    /// no-signal fallback, `SUBSTITUTE_ALPHA == 0.17`). This port always
    /// uses that same fallback alpha and computes `mean_r`/`mean_ir` from
    /// THIS frame's own response-converted R and IR samples (rail-excluded
    /// to the 1st-99th percentile, mirroring `processing::nikonlook`'s
    /// `unclipped_percentiles` rail-exclusion pattern) rather than a real
    /// prepass's reduced calibration sums. Never divides by zero or
    /// produces non-finite output on degenerate input (uniform frame,
    /// single-pixel frame) -- threat T-16-03.
    pub fn for_main_scan(frame: &IceInputFrame) -> IceParameters {
        let lut = generate_response_lut();
        let r_values: Vec<f64> = frame
            .rgb
            .iter()
            .map(|px| convert_response(px[0], &lut) as f64)
            .collect();
        let ir_values: Vec<f64> = frame
            .ir
            .iter()
            .map(|&sample| convert_response(sample, &lut) as f64)
            .collect();
        let mean_r = rail_excluded_mean(&r_values);
        let mean_ir = rail_excluded_mean(&ir_values);

        let base_primary = ((mean_ir - SUBSTITUTE_ALPHA * mean_r) / (1.0 - SUBSTITUTE_ALPHA)) as f32;

        IceParameters {
            base_primary,
            base_addend: f32::from_bits(0xC2EED000),
            scale: f32::from_bits(0xBA887952),
            offset: f32::from_bits(0x3F800000),
            floor: f32::from_bits(0x3CA3D70A),
            resolution_metric: 4000,
            horizontal_minimum_resolution_cutoff: 550,
            sample_threshold: f32::from_bits(0x4740E73C),
            count_limit: 8,
            perpendicular_radius: 4,
            cross_neighbor_cutoff: 1_600,
            coarse_enabled: true,
            coarse_reference: base_primary,
            coarse_slopes: [f32::from_bits(0x3F8CCCCD); 3],
            band_enabled: [true, true, true],
            band_scales: [f32::from_bits(0x3FA00000); 3],
            factors_a: [
                [
                    f32::from_bits(0x3F9AE148),
                    f32::from_bits(0x3F9D70A4),
                    f32::from_bits(0x3F90A3D7),
                ],
                [
                    f32::from_bits(0x3F95C28F),
                    f32::from_bits(0x3F91EB85),
                    f32::from_bits(0x3F8A3D71),
                ],
                [
                    f32::from_bits(0x3F851EB8),
                    f32::from_bits(0x3F6E147B),
                    f32::from_bits(0x3F7851EC),
                ],
            ],
            factors_b: [
                [
                    f32::from_bits(0x3F8B851F),
                    f32::from_bits(0x3F90A3D7),
                    f32::from_bits(0x3F851EB8),
                ],
                [
                    f32::from_bits(0x3F8A3D71),
                    f32::from_bits(0x3F866666),
                    f32::from_bits(0x3F828F5C),
                ],
                [
                    f32::from_bits(0x3F75C28F),
                    f32::from_bits(0x3F570A3D),
                    f32::from_bits(0x3F63D70A),
                ],
            ],
            configured_strengths: [0.0, 0.0, 0.0],
            driver_gate_primary: true,
            driver_gate_secondary: true,
            row_reconstruction_gate: 0,
            dither_scales: [
                f32::from_bits(0x3C75C28F),
                f32::from_bits(0x3C75C28F),
                f32::from_bits(0x3CCCCCCD),
            ],
        }
    }
}

/// Per-pixel defect severity, normalized to `[0.0, 1.0]`: `0.0` = clean,
/// `1.0` = most severe / least certain. This is a RENORMALIZED convention,
/// deliberately independent of the real `continuous_score`'s own internal
/// raw polarity/range: the real function's raw output is bounded to
/// `[floor, 1.0]`, where `1.0` (its ceiling) is CLEAN and `floor` (its
/// minimum, ~0.02 under this profile) is the MOST SEVERE signal it can
/// express -- confirmed empirically during this plan's execution (a live
/// invocation of the real `continuous_score` against a synthetic
/// defect-injected frame bottoms out exactly at `floor` on the injected
/// defect and reads exactly `1.0` on every clean pixel). This module
/// renormalizes via `(1.0 - raw) / (1.0 - floor)`, clamped to `[0.0, 1.0]`,
/// so the public field is UI-ready for Phase 17's red (mid-range, "will
/// correct") / amber (near `1.0`, "uncertain") design without Phase 17
/// needing to know the internal polarity.
#[derive(Debug, Clone, PartialEq)]
pub struct DefectMap {
    pub width: u32,
    pub height: u32,
    pub score: Vec<f32>,
}

// ---------------------------------------------------------------------
// Response-LUT conversion
// (x3a.py: generate_nikon_response_lut, SharedLookupInputResponse.convert)
// ---------------------------------------------------------------------

/// Response-LUT conversion: raw u16 count -> working float response value.
/// Ported from `x3a.py`'s `generate_nikon_response_lut` (line 111): binary64
/// intermediates (`65535.0 * log2(domain + 1.0) / 16.0`), one final float32
/// narrowing per entry. Table has exactly 65536 entries (index = raw
/// count). Verified during this plan's execution via a live invocation of
/// the real function: index 0 -> exactly 0.0, index 65535 -> exactly
/// 65535.0 (65536 == 2^16, so `log2(65536.0) == 16.0` exactly under
/// IEEE754), monotonically non-decreasing in between (a logarithmic
/// response curve, not linear). This port does not replicate the real
/// function's own SHA256 platform-reproducibility hash check
/// (`NIKON_RESPONSE_LUT_SHA256`) -- that check exists to prove bit-parity
/// with Nikon's OWN recovered firmware constants across platforms; this
/// port's own correctness is verified directly against a live invocation of
/// the real function (see this module's Group L tests), not by reproducing
/// that specific hash.
pub fn generate_response_lut() -> [f32; 65536] {
    let mut table = [0f32; 65536];
    for (raw, slot) in table.iter_mut().enumerate() {
        let domain = raw as f64;
        let value = 65535.0 * (domain + 1.0).log2() / 16.0;
        *slot = value as f32;
    }
    table
}

/// Converts one raw RGBI pixel sample through the response LUT. Ported from
/// `x3a.py`'s `SharedLookupInputResponse.convert` (lines 157-163), which is
/// a direct table lookup (`self.table[pixels]`) once the shared table is
/// built -- no per-call arithmetic.
pub fn convert_response(raw: u16, lut: &[f32; 65536]) -> f32 {
    lut[raw as usize]
}

// ---------------------------------------------------------------------
// Percentile / rail-excluded mean primitive (single-acquisition
// base_primary substitute -- see IceParameters::for_main_scan). No real
// x3a.py/profile.py equivalent exists for this specific helper (the real
// package always has a genuine prepass capture to reduce instead); this
// mirrors processing::nikonlook's own unclipped_percentiles/
// percentile_linear rail-exclusion pattern (a private copy here, matching
// processing::geometry's own precedent of a private percentile_linear
// copy rather than a shared kernel module).
// ---------------------------------------------------------------------

/// NumPy's default "linear" percentile interpolation on an ALREADY SORTED
/// ascending slice. `p` is in `[0, 100]`.
fn percentile_linear(sorted: &[f64], p: f64) -> f64 {
    let n = sorted.len();
    debug_assert!(n > 0, "percentile_linear requires a non-empty slice");
    if n == 1 {
        return sorted[0];
    }
    let idx = (p / 100.0) * (n - 1) as f64;
    let lo_idx = idx.floor() as usize;
    let hi_idx = idx.ceil() as usize;
    if lo_idx == hi_idx {
        return sorted[lo_idx];
    }
    let frac = idx - lo_idx as f64;
    sorted[lo_idx] * (1.0 - frac) + sorted[hi_idx] * frac
}

/// Mean of `values`, excluding samples outside the 1st-99th percentile
/// range (rail exclusion, mirroring `processing::nikonlook`'s
/// `unclipped_percentiles`), falling back to the full population's mean if
/// the trimmed subset is empty (degenerate/tiny input -- never divides by
/// zero, never panics: threat T-16-03). On a fully uniform input (every
/// value identical), P1 == P99 == that value, so every sample survives the
/// trim and the result is exactly that value. Returns `0.0` on an empty
/// slice (never expected in practice -- `IceInputFrame` should always carry
/// at least one pixel -- but this port never panics on frame-derived input).
fn rail_excluded_mean(values: &[f64]) -> f64 {
    if values.is_empty() {
        return 0.0;
    }
    let mut sorted = values.to_vec();
    sorted.sort_by(f64::total_cmp);
    let lo = percentile_linear(&sorted, 1.0);
    let hi = percentile_linear(&sorted, 99.0);
    let trimmed: Vec<f64> = values.iter().copied().filter(|&v| v >= lo && v <= hi).collect();
    let source: &[f64] = if trimmed.is_empty() { &sorted } else { &trimmed };
    source.iter().sum::<f64>() / source.len() as f64
}

// ---------------------------------------------------------------------
// Auxiliary signal (x3a.py: AuxiliaryParameters, derive_auxiliary,
// lines 167-221)
// ---------------------------------------------------------------------

/// Ported from `x3a.py`'s `derive_auxiliary` (lines 193-221), fixed to this
/// profile's own constants: `selected_visible_channel = 0` (R --
/// `profile.py`'s `auxiliary_parameters` always selects channel 0),
/// `calibration_offset = 1.0` (`profile.py`: `float(np.float32(1.0))`), and
/// `alpha = SUBSTITUTE_ALPHA` (the same single-acquisition substitute as
/// `IceParameters::for_main_scan`'s `base_primary` -- `profile.py`'s
/// `auxiliary_parameters` sets its own `alpha` field from the identical
/// `record.observed_main_alpha` value `_base_primary` reads, scaled by
/// `auxiliary_factor_b = 1.0`, so reusing the same substitute for both call
/// sites is the correct, consistent single-acquisition adaptation, not an
/// independently invented value).
///
/// The real function's `alpha == 1.0` special case (returning
/// `alpha_one_replacement` uniformly) is OMITTED here: with `alpha` fixed
/// at `SUBSTITUTE_ALPHA == 0.17`, that branch is provably unreachable (0.17
/// != 1.0 always), so this port has no `alpha_one_replacement`/
/// `base_primary` parameter at all -- mirroring `processing::nikonlook`'s
/// own precedent of omitting `MonotoneCurve`'s never-read `decreasing`
/// field.
fn derive_auxiliary_plane(working_r: &[f32], working_ir: &[f32]) -> Vec<f32> {
    debug_assert_eq!(working_r.len(), working_ir.len());
    // Narrow-then-widen, matching the real source's own
    // `float(np.float32(parameters.calibration_offset))` construction, so
    // this substitute's arithmetic uses the exact same bit pattern the real
    // algorithm would after its own float32 round trip.
    let offset: f64 = (1.0f32) as f64;
    working_r
        .iter()
        .zip(working_ir.iter())
        .map(|(&r, &ir)| {
            let visible = r as f64;
            let infrared = ir as f64;
            let auxiliary = (infrared - SUBSTITUTE_ALPHA * visible) / (1.0 - SUBSTITUTE_ALPHA) - offset;
            auxiliary as f32
        })
        .collect()
}

// ---------------------------------------------------------------------
// Continuous defect score (x3a.py: ScoreParameters, continuous_score,
// lines 225-286)
// ---------------------------------------------------------------------

/// The `continuous_score` formula (`x3a.py` lines 245-286) applied to ONE
/// sample, with no horizontal smoothing. `continuous_score_plane` calls
/// this once per (possibly filtered) sample for the real, public score;
/// `is_confirmed`'s neighbor corroboration check (below) ALSO calls this
/// directly on UNFILTERED per-pixel auxiliary values -- see that function's
/// own doc comment for why the two need different inputs.
fn single_pixel_severity(auxiliary: f32, params: &IceParameters) -> f32 {
    let primary = params.base_primary as f64;
    let addend = params.base_addend as f64;
    let scale = params.scale as f64;
    let offset = params.offset as f64;
    let floor = params.floor as f64;
    let raw = ((primary + addend) - auxiliary as f64) * scale + offset;
    let clamped = raw.min(1.0).max(floor);
    clamped as f32
}

/// Ported from `x3a.py`'s `continuous_score` (lines 245-286): a per-pixel
/// affine score computed from the auxiliary plane, clamped to
/// `[floor, 1.0]`. `horizontal_minimum`
/// (`horizontal_minimum_resolution_cutoff < resolution_metric`) is always
/// `true` under this profile's fixed constants (550 < 4000), so this port
/// always applies the real function's 3-tap horizontal minimum filter
/// (`min` of each pixel and its immediate left/right row neighbors) over
/// interior columns before scoring -- computed from the ORIGINAL
/// (unfiltered) auxiliary row, matching NumPy's own vectorized
/// `np.minimum(values[:, :-2], values[:, 1:-1], values[:, 2:])`, which
/// reads from the pre-mutation `values` array while writing into a
/// separate `sample` copy. Edge columns (first/last) are never filtered,
/// matching the real function's own `[:, 1:-1]` slice bounds.
///
/// Verified during this plan's execution: this smoothing step measurably
/// SPREADS a defect's depressed score into its immediate left/right
/// neighbor column within the same row (a 2-column-wide raw auxiliary dip
/// reads as a 4-column-wide depressed score after this filter, and a
/// 1-column-wide isolated spike reads as a 3-column-wide depressed score)
/// -- a real, faithful characteristic of the ported algorithm, not a bug in
/// this port. See `is_confirmed`'s doc comment for why this smear is
/// deliberately NOT used when deciding neighbor corroboration.
fn continuous_score_plane(auxiliary: &[f32], width: usize, height: usize, params: &IceParameters) -> Vec<f32> {
    let mut sample = auxiliary.to_vec();
    let horizontal_minimum = params.horizontal_minimum_resolution_cutoff < params.resolution_metric;
    if horizontal_minimum && width > 2 {
        for y in 0..height {
            let row_start = y * width;
            let row = &auxiliary[row_start..row_start + width];
            for x in 1..width - 1 {
                sample[row_start + x] = row[x - 1].min(row[x]).min(row[x + 1]);
            }
        }
    }
    sample.iter().map(|&value| single_pixel_severity(value, params)).collect()
}

// ---------------------------------------------------------------------
// Whole-frame neighborhood confirmation
// ADAPTED from x3a.py's evaluate_normal_decision / DecisionOffsets /
// evaluate_normal_auxiliary_decision (lines 351-587) -- NOT a byte-exact
// port. See the doc comment below for the full rationale.
// ---------------------------------------------------------------------

/// Whole-frame neighborhood confirmation for one candidate pixel.
///
/// This is an ADAPTATION of the real `evaluate_normal_decision`/
/// `evaluate_normal_auxiliary_decision` (`x3a.py` lines 452-589), not a
/// byte-exact port, for two independently verified reasons (both checked
/// by directly running the real functions during this plan's execution,
/// per plan 16-01's `<ground_truth_methodology>`):
///
/// 1. **Structure.** The real functions test 4 DISJOINT bars, each 9
///    samples long, offset `perpendicular_radius` pixels AWAY from (never
///    including) the candidate pixel (`DecisionOffsets.captured_normal_ls5000`).
///    Verified empirically: with the profile's own fixed
///    `perpendicular_radius = 4`, neither a 2-pixel-wide injected defect
///    (this plan's own Task 1 Group A fixture) nor a 1-pixel isolated spike
///    ever reaches those far bars -- both are far smaller than the
///    mandatory 4-pixel offset. A literal port of that structure therefore
///    cannot distinguish "genuine small defect" from "isolated single-pixel
///    noise" at all: both read as `group_fallback == False` either way.
///    This port instead uses a single, unified square neighborhood of
///    Chebyshev radius `perpendicular_radius`, CENTERED ON the candidate
///    pixel (excluding the pixel itself) -- matching this plan's own
///    `<interfaces>` suggestion of "a fixed-radius 2D neighborhood scan ...
///    centered on each candidate pixel."
/// 2. **Per-neighbor test.** The real functions compare raw auxiliary
///    directly against the fixed hardware constant
///    `DecisionParameters.sample_threshold` (49383.234375). Verified
///    empirically: running this plan's own required Task 1 Group A
///    fixture (`tests/conftest.py`'s own defect-injection pattern, main IR
///    dropped to 9,000) through the REAL `derive_auxiliary`/
///    `continuous_score` produced a defect auxiliary of ~53,390 --
///    comfortably ABOVE `sample_threshold`, even though `continuous_score`
///    itself already reports that same location at its most severe
///    (`floor`). `sample_threshold` is calibrated for the real
///    prepass-reduced pipeline's absolute auxiliary scale; it does not
///    transfer to this port's single-acquisition `base_primary` substitute,
///    whose absolute level is frame-relative (see
///    `IceParameters::for_main_scan`). A literal `< sample_threshold`
///    neighbor test would find zero qualifying neighbors even for this
///    plan's own required-passing defect fixture. Instead, each neighbor's
///    own severity is computed via `single_pixel_severity` on its
///    UNFILTERED auxiliary value (this frame's own
///    `base_primary`/`base_addend`/`scale`/`offset`/`floor`, i.e. the same
///    formula `continuous_score_plane` uses, but WITHOUT its horizontal
///    smear -- verified empirically that the smear alone creates false
///    corroborating neighbors immediately beside a genuinely isolated
///    single-pixel spike, which would otherwise defeat noise rejection),
///    and compared against the floor/ceiling midpoint: a frame-relative,
///    scale-adaptive severity cutoff instead of an absolute hardware
///    constant. `sample_threshold` is still transcribed into
///    `IceParameters` (see Task 1's Group P test) since it is a real, fixed
///    profile constant this project retains for provenance/future
///    recalibration, even though this adapted confirmation step does not
///    consume it directly.
///
/// `count_limit` keeps its real, literal role as an upper bound: reject
/// (treat as unconfirmed) if MORE than `count_limit` neighbors also read
/// defect-like, mirroring the real `group_fallback`'s "give up, the whole
/// area is too damaged to localize a discrete point defect" intent. This
/// port ADDS a lower bound the real functions do not have: reject if ZERO
/// neighbors corroborate (a truly isolated single-pixel anomaly) --
/// nothing in the ported functions' own scope handles point-defect-vs-noise
/// discrimination on a whole, in-memory frame (the real streaming
/// pipeline's row-history/hidden-startup-row machinery, out of scope per
/// this plan's `<scope_map>`, may have handled an analogous concern
/// upstream in a way this port cannot reproduce without that machinery).
///
/// Note: a pixel that is itself genuinely clean, with a genuinely clean
/// neighborhood, also has zero corroborating neighbors and is rejected here
/// -- harmless, since its own renormalized score is already `0.0` either
/// way (see `detect_defects`).
fn is_confirmed(y: usize, x: usize, width: usize, height: usize, auxiliary: &[f32], params: &IceParameters) -> bool {
    let radius = params.perpendicular_radius as i64;
    let midpoint = (params.floor + 1.0) / 2.0;
    let mut low_count: u32 = 0;
    for dy in -radius..=radius {
        for dx in -radius..=radius {
            if dy == 0 && dx == 0 {
                continue;
            }
            let ny = y as i64 + dy;
            let nx = x as i64 + dx;
            if ny < 0 || ny >= height as i64 || nx < 0 || nx >= width as i64 {
                continue;
            }
            let neighbor_aux = auxiliary[(ny as usize) * width + (nx as usize)];
            if single_pixel_severity(neighbor_aux, params) < midpoint {
                low_count += 1;
            }
        }
    }
    low_count >= 1 && low_count <= params.count_limit
}

// ---------------------------------------------------------------------
// Whole-frame defect-map assembly (detect_defects entry point)
// ---------------------------------------------------------------------

/// Whole-frame defect-map assembly: response-converts every R and IR
/// sample, derives the auxiliary (IR-differential) signal, computes the
/// continuous per-pixel score, applies the neighborhood noise-confirmation
/// check (`is_confirmed`), and renormalizes into this module's own public
/// `[0.0, 1.0]` (0=clean, 1=severe) convention -- see `DefectMap`'s doc
/// comment for the exact renormalization formula and rationale.
/// Unconfirmed score-spikes (isolated single-pixel noise that fails
/// `is_confirmed`) read back as exactly `0.0`, not a nonzero-but-unconfirmed
/// value. Never mutates `frame` (takes `&IceInputFrame`; enforced
/// structurally by the borrow checker, and reinforced by an explicit
/// regression test -- see Group Z below).
pub fn detect_defects(frame: &IceInputFrame, params: &IceParameters) -> DefectMap {
    let width = frame.width as usize;
    let height = frame.height as usize;
    let lut = generate_response_lut();

    let working_r: Vec<f32> = frame.rgb.iter().map(|px| convert_response(px[0], &lut)).collect();
    let working_ir: Vec<f32> = frame.ir.iter().map(|&sample| convert_response(sample, &lut)).collect();

    let auxiliary = derive_auxiliary_plane(&working_r, &working_ir);
    let raw_score = continuous_score_plane(&auxiliary, width, height, params);

    // Renormalization denominator, guarded against a degenerate floor >= 1.0
    // (never expected given ScoreParameters's own floor <= 1.0 invariant in
    // the real source, but this port never panics on frame- or
    // parameter-derived floating point -- threat T-16-03).
    let denom = (1.0f32 - params.floor).max(1e-9);

    let mut score = vec![0f32; width * height];
    for y in 0..height {
        for x in 0..width {
            let idx = y * width + x;
            if is_confirmed(y, x, width, height, &auxiliary, params) {
                score[idx] = ((1.0 - raw_score[idx]) / denom).clamp(0.0, 1.0);
            }
            // else: leave at 0.0 -- rejected as unconfirmed noise.
        }
    }

    DefectMap {
        width: frame.width,
        height: frame.height,
        score,
    }
}

