/// `pad_reconstruction_history` ADAPTATION DECISION (plan 16-02's own
/// required investigation before porting -- see that plan's Task 1
/// `<action>`): read directly during this plan's execution,
/// `pad_reconstruction_history` (reconstruction.py line 39) is NOT ported.
/// Two independent findings, both checked directly against the real source
/// tree, support skipping it entirely rather than adapting it:
///
/// 1. **Zero real callers.** `grep -rn "pad_reconstruction_history" src/`
///    across the ENTIRE `portable-digital-ice` package finds only its own
///    `def` line -- no caller anywhere, not even inside `reconstruction.py`
///    itself. The real, live streaming pipeline (`streaming.py`'s
///    `_history_window`, read directly for this evidence though not
///    ported -- excluded per plan 16-01's `<scope_map>`) reimplements an
///    equivalent padded-history buffer inline instead of calling this
///    function: `pad_reconstruction_history` is orphaned legacy code in
///    the real package, not a load-bearing dependency of the
///    candidate-generation math this plan ports.
/// 2. **What it encodes is a streaming/hidden-startup-row concern.**
///    `_history_window`'s real padding is ASYMMETRIC per side: the row
///    immediately above the frame is filled with `score_floor`-weighted
///    extrapolation of the first row (a hidden-calibration-row artifact),
///    the row below the frame replicates the last row, and ALL horizontal
///    (column) guards are pure zero on every side. This whole-frame
///    in-memory port has no hidden startup rows and no row-history ring
///    buffer at all (per plan 16-01's own exclusion of that architecture)
///    -- there is nothing for a `pseudo_top_row`/"final flush repeats the
///    last row" convention to mean here.
///
/// This port's own adaptation, used by every neighborhood extraction below
/// (`extract_scalar_patch_9x9`/`extract_rgb_patch_9x9`): **uniform
/// zero-padding on all four sides.** A genuine simplification, not a
/// byte-exact reproduction of the real asymmetric convention -- justified
/// because (a) it already matches the real convention's OWN choice on the
/// majority of sides (left/right always, and everything more than one row
/// beyond top), (b) a phantom zero-score neighbor contributes exactly zero
/// weight to every weighted-average denominator this plan's math computes
/// (see `recovered_rgb_candidates` below), so it self-excludes from the
/// average rather than skewing it toward a fabricated value, and (c) it
/// can never panic or divide by a negative/NaN quantity
/// (`recovered_rgb_candidates`'s own `NonpositiveNormalizerPolicy` already
/// defines a fallback for an entirely-phantom neighborhood, e.g. a defect
/// on a frame smaller than 9x9) -- satisfying threat T-16-05 by
/// construction, not by a bolted-on edge-case branch.
fn extract_scalar_patch_9x9(plane: &[f32], width: usize, height: usize, cy: usize, cx: usize) -> [[f32; 9]; 9] {
    let mut patch = [[0f32; 9]; 9];
    for dy in -4i64..=4 {
        let py = cy as i64 + dy;
        if py < 0 || py >= height as i64 {
            continue;
        }
        for dx in -4i64..=4 {
            let px = cx as i64 + dx;
            if px < 0 || px >= width as i64 {
                continue;
            }
            patch[(dy + 4) as usize][(dx + 4) as usize] = plane[(py as usize) * width + (px as usize)];
        }
    }
    patch
}

/// RGB counterpart of [`extract_scalar_patch_9x9`] -- identical zero-padded
/// Chebyshev-radius-4 neighborhood extraction, one `[f32; 3]` per cell.
fn extract_rgb_patch_9x9(
    plane: &[[f32; 3]],
    width: usize,
    height: usize,
    cy: usize,
    cx: usize,
) -> [[[f32; 3]; 9]; 9] {
    let mut patch = [[[0f32; 3]; 9]; 9];
    for dy in -4i64..=4 {
        let py = cy as i64 + dy;
        if py < 0 || py >= height as i64 {
            continue;
        }
        for dx in -4i64..=4 {
            let px = cx as i64 + dx;
            if px < 0 || px >= width as i64 {
                continue;
            }
            patch[(dy + 4) as usize][(dx + 4) as usize] = plane[(py as usize) * width + (px as usize)];
        }
    }
    patch
}

/// Nonpositive-normalizer fallback policy. Ported from reconstruction.py's
/// `NonpositiveNormalizerPolicy` (a `str` Enum with two members). The real,
/// live production call sites (`startup.py`/`streaming.py`) never override
/// `recovered_rgb_candidates`'s own default (`UnnormalizedSum`), so
/// `Invalid` is only ever constructed by this module's own test suite
/// (Group W-degenerate) -- retained for a complete, faithful port of the
/// real enum's full surface, not because `heal` itself needs it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NonpositiveNormalizerPolicy {
    UnnormalizedSum,
    // Never constructed by this port's own production call site (`heal`,
    // plan 16-02 Task 3, always passes UnnormalizedSum -- matching the
    // real `startup.py`/`streaming.py`, which never override
    // `recovered_rgb_candidates`'s own UNNORMALIZED_SUM default). Retained
    // for a complete, faithful port of the real enum's full surface and
    // exercised directly by this module's own test suite (Group
    // W-degenerate).
    #[allow(dead_code)]
    Invalid,
}

/// One multiscale reconstruction candidate: an RGB estimate plus the raw
/// normalizer that produced it and a validity flag. Ported from
/// reconstruction.py's `Candidate` (a frozen dataclass).
#[derive(Debug, Clone, Copy, PartialEq)]
struct Candidate {
    rgb: [f32; 3],
    normalizer: f32,
    valid: bool,
}

/// Ported from `_vertical_scratch`'s per-column inner loop, applied to one
/// column of 9 vertically-stacked values (row 0 = top of the 9x9 patch).
/// Returns `(S3, S5, S7, S9)` -- Nikon's recovered vertical partial sums
/// over centered windows of height 3/5/7/9, in that add order. The real
/// source keeps a SINGLE f64 (Python `float`) accumulator running across
/// all four checkpoints and takes an f32 SNAPSHOT at each one (never
/// re-reading the narrowed snapshot back into the accumulator) -- this
/// port preserves that exact snapshot schedule, not a simpler "narrow
/// after every step" or "stay in f64 throughout" alternative, since both
/// would produce different last-bit results than the real function.
fn vertical_scratch_column(col: [f32; 9]) -> (f32, f32, f32, f32) {
    let mut acc = col[3] as f64 + col[4] as f64;
    acc += col[5] as f64;
    let s3 = acc as f32;
    acc += col[2] as f64;
    acc += col[6] as f64;
    let s5 = acc as f32;
    acc += col[1] as f64;
    acc += col[7] as f64;
    let s7 = acc as f32;
    acc += col[0] as f64;
    acc += col[8] as f64;
    let s9 = acc as f32;
    (s3, s5, s7, s9)
}

/// Ported from `_vertical_binomial_16`'s per-column inner loop: the
/// vertical half of Nikon's 3x3 binomial `[1,2,1]` filter (rows 3/4/5 of
/// the 9x9 patch), scaled by a float32-narrowed `1/16` coefficient (the
/// real source's own doc comment: this unusual float32-narrow-then-widen
/// split, rather than 1/4 at each of two passes, is observable in last
/// bits -- preserved exactly).
fn vertical_binomial_16_column(col: [f32; 9]) -> f32 {
    let coefficient = (1.0f32 / 16.0) as f64;
    let center = col[4] as f64;
    let mut acc = col[3] as f64 + center;
    acc += col[5] as f64;
    acc += center;
    (acc * coefficient) as f32
}

/// Ported from `_recovered_unscaled_averages`, specialized to one scalar
/// channel (used directly for the score/weight-normalizer path below, and
/// as the shared per-channel building block for
/// `recovered_rgb_unscaled_averages`). Returns `(Q69, Q21, Q16)` in
/// widened f64 precision, before any candidate narrowing.
fn recovered_unscaled_averages_scalar(patch: &[[f32; 9]; 9]) -> (f64, f64, f64) {
    let mut s3 = [0f32; 9];
    let mut s5 = [0f32; 9];
    let mut s7 = [0f32; 9];
    let mut s9 = [0f32; 9];
    let mut bin16 = [0f32; 9];
    for col in 0..9 {
        let column: [f32; 9] = std::array::from_fn(|row| patch[row][col]);
        let (a, b, c, d) = vertical_scratch_column(column);
        s3[col] = a;
        s5[col] = b;
        s7[col] = c;
        s9[col] = d;
        bin16[col] = vertical_binomial_16_column(column);
    }
    let coefficient_69 = (1.0f32 / 69.0) as f64;
    let coefficient_21 = (1.0f32 / 21.0) as f64;

    let mut total_21 = s3[6] as f64 + s3[2] as f64;
    total_21 += s5[3] as f64;
    total_21 += s5[4] as f64;
    total_21 += s5[5] as f64;

    let mut total_69 = s5[8] as f64 + s5[0] as f64;
    total_69 += s7[1] as f64;
    total_69 += s7[7] as f64;
    for col in 2..7 {
        total_69 += s9[col] as f64;
    }

    let mut total_16 = bin16[4] as f64 + bin16[3] as f64;
    total_16 += bin16[5] as f64;
    total_16 += bin16[4] as f64;

    (total_69 * coefficient_69, total_21 * coefficient_21, total_16)
}

/// Ported from `recovered_spatial_averages`: stored Q69/Q21/Q16 floats for
/// a scalar 9x9 patch (the score-normalizer path -- Nikon's W69/W21/W16).
/// `heal` (Task 3) derives its own weight normalizers via
/// `weight_and_auxiliary_record_for_pixel` -> `recovered_unscaled_averages_scalar`
/// directly (needing the paired auxiliary numerator too), not through this
/// function -- like `recovered_multiscale_candidates` (its only other
/// caller), this is real, correct, ground-truth-verified (Group C1) code
/// with no production call site in this port, so it is `#[cfg(test)]`-scoped.
#[cfg(test)]
fn recovered_spatial_averages(patch: &[[f32; 9]; 9]) -> [f32; 3] {
    let (q69, q21, q16) = recovered_unscaled_averages_scalar(patch);
    [q69 as f32, q21 as f32, q16 as f32]
}

/// Ported from `_recovered_rgb_unscaled_averages`: reuses
/// `recovered_unscaled_averages_scalar`'s Q69/Q21 per channel unchanged,
/// but OVERRIDES the Q16 slot with a differently-ordered computation (the
/// real source's own doc comment: the W/A path stores a vertically
/// filtered float32 intermediate, while this RGB path builds three
/// horizontal `[1,2,1]` rows first, combines them vertically, and applies
/// the `1/16` coefficient once at the end -- observable in the last bit,
/// must not be folded into the scalar helper above). Returns
/// `result[metric][channel]`, `metric` 0=Q69, 1=Q21, 2=Q16.
fn recovered_rgb_unscaled_averages(patch: &[[[f32; 3]; 9]; 9]) -> [[f64; 3]; 3] {
    let mut result = [[0f64; 3]; 3];
    for channel in 0..3 {
        let scalar_patch: [[f32; 9]; 9] =
            std::array::from_fn(|row| std::array::from_fn(|col| patch[row][col][channel]));
        let (q69, q21, _q16_unused) = recovered_unscaled_averages_scalar(&scalar_patch);
        result[0][channel] = q69;
        result[1][channel] = q21;
    }
    let coefficient = (1.0f32 / 16.0) as f64;
    for channel in 0..3 {
        let mut rows = [0f64; 3];
        for (i, &y) in [3usize, 4, 5].iter().enumerate() {
            let center = patch[y][4][channel] as f64;
            let mut horizontal = patch[y][3][channel] as f64 + patch[y][5][channel] as f64;
            horizontal += center;
            horizontal += center;
            rows[i] = horizontal;
        }
        let mut total = rows[0] + rows[1];
        total += rows[1];
        total += rows[2];
        result[2][channel] = total * coefficient;
    }
    result
}

/// Ported from `recovered_rgb_candidates`: build C69/C21/C16 from Nikon's
/// explicit float32 W normalizers (`weight_record[..3]`), NOT re-derived
/// from a separately-passed score patch -- confirmed via direct grep as
/// the REAL, live call convention: both `startup.py` and `streaming.py`
/// call this exact function with a weight record's `[:3]` slice as
/// `normalizers`, never `recovered_multiscale_candidates`'s self-contained
/// convenience path below (see that function's own doc comment for the
/// full evidence). This is the function `heal` itself calls.
fn recovered_rgb_candidates(
    weighted_patch: &[[[f32; 3]; 9]; 9],
    normalizers: [f32; 3],
    policy: NonpositiveNormalizerPolicy,
) -> [Candidate; 3] {
    let averages = recovered_rgb_unscaled_averages(weighted_patch);
    std::array::from_fn(|metric| {
        let denominator = normalizers[metric];
        let rgb: [f32; 3] = if denominator > 0.0 {
            let reciprocal = 1.0f64 / denominator as f64;
            std::array::from_fn(|c| (averages[metric][c] * reciprocal) as f32)
        } else if policy == NonpositiveNormalizerPolicy::UnnormalizedSum {
            std::array::from_fn(|c| averages[metric][c] as f32)
        } else {
            [0.0; 3]
        };
        let valid = rgb.iter().all(|v| v.is_finite() && *v > 0.0);
        Candidate { rgb, normalizer: denominator, valid }
    })
}

/// Ported from `recovered_multiscale_candidates`: Nikon's C69/C21/C16
/// candidates from ONE centered 9x9 patch, deriving its own
/// score-normalizer record via `recovered_spatial_averages`. The real
/// source's own docstring calls this a "convenience entry point"; direct
/// grep across the whole package confirms it has ZERO callers anywhere
/// outside its own definition -- the real, live pipeline always uses the
/// split `recovered_weight_and_auxiliary_records_for_interior_row`
/// (adapted below as `weight_and_auxiliary_record_for_pixel`) +
/// `recovered_rgb_candidates` path instead, reusing one weight record for
/// both the RGB candidates AND the feature/auxiliary records Task 2's band
/// combination needs. Ported and tested (Group C2) per this plan's own
/// explicit instruction -- a self-contained, correct, real function, just
/// not the one `heal` calls internally, so it is `#[cfg(test)]`-scoped
/// rather than carrying a production call site it does not have.
#[cfg(test)]
fn recovered_multiscale_candidates(
    weighted_patch: &[[[f32; 3]; 9]; 9],
    score_patch: &[[f32; 9]; 9],
    policy: NonpositiveNormalizerPolicy,
) -> [Candidate; 3] {
    let normalizers = recovered_spatial_averages(score_patch);
    recovered_rgb_candidates(weighted_patch, normalizers, policy)
}

/// Ported/adapted from `recovered_weight_records_for_interior_row` +
/// `recovered_weight_and_auxiliary_records_for_interior_row`, collapsed
/// from "records for one row, using a history buffer" to "one record for
/// one pixel, using a directly-extracted neighborhood" -- the per-row
/// batching in the real source is a streaming/vectorization convenience
/// (per this plan's own `<scope_map>` note on the "_for_interior_row"
/// naming), not a behavioral requirement; this adaptation produces the
/// same weight/auxiliary values for the same neighborhood content.
/// Verified directly against `_startup_feature_record`
/// (`startup.py`, read for this evidence though not ported): the real
/// per-pixel call site builds exactly this pair (`weights`, `feature`) via
/// the SAME shared normalizer, then reuses `weights[..3]` for
/// `recovered_rgb_candidates` and `weights[3]` (a bare copy of the
/// pixel's own raw score) for `driver_forces_fallback` -- confirming this
/// one function safely replaces both real per-row functions for this
/// port's whole-frame, per-pixel access pattern.
///
/// `score_plane`/`auxiliary_plane`/`weighted_auxiliary_plane` are the
/// whole-frame planes (row-major, `width*height` each);
/// `weighted_auxiliary_plane[i]` must equal `score_plane[i] *
/// auxiliary_plane[i]` (the caller's responsibility -- mirrors the real
/// source computing this product once per needed window rather than per
/// output pixel). Returns `(weight_record, auxiliary_record)`, each
/// `[metric69, metric21, metric16, metric1]` where `metric1` is the
/// pixel's own unfiltered value (not spatially averaged).
///
/// The real source's own critical precision note (preserved here exactly):
/// each auxiliary-record lane divides by the UNROUNDED f64 weight
/// normalizer, not the float32-narrowed `weight_record` value just
/// computed -- dividing by the narrowed value is off by one ULP on a
/// substantial minority of samples.
fn weight_and_auxiliary_record_for_pixel(
    score_plane: &[f32],
    auxiliary_plane: &[f32],
    weighted_auxiliary_plane: &[f32],
    width: usize,
    height: usize,
    y: usize,
    x: usize,
    fallback: f32,
) -> ([f32; 4], [f32; 4]) {
    let score_patch = extract_scalar_patch_9x9(score_plane, width, height, y, x);
    let weighted_aux_patch = extract_scalar_patch_9x9(weighted_auxiliary_plane, width, height, y, x);

    let (q69_w, q21_w, q16_w) = recovered_unscaled_averages_scalar(&score_patch);
    let (q69_a, q21_a, q16_a) = recovered_unscaled_averages_scalar(&weighted_aux_patch);
    let unrounded = [q69_w, q21_w, q16_w];
    let numerator = [q69_a, q21_a, q16_a];

    let mut weight_record = [0f32; 4];
    let mut auxiliary_record = [0f32; 4];
    for lane in 0..3 {
        weight_record[lane] = unrounded[lane] as f32;
        auxiliary_record[lane] = if unrounded[lane] > 0.0 { (numerator[lane] / unrounded[lane]) as f32 } else { fallback };
    }
    let center_index = y * width + x;
    weight_record[3] = score_plane[center_index];
    auxiliary_record[3] = if weight_record[3] > 0.0 { auxiliary_plane[center_index] } else { fallback };
    (weight_record, auxiliary_record)
}

