/// DEAD-CODE FINDING (documented, not a plan deviation to silently apply
/// without evidence): direct grep across the ENTIRE `portable-digital-ice`
/// source tree confirms `combine_multiscale_bands`/`dead_zone_residual`/
/// `select_feature_band_extrema`/`BandLimits` have callers ONLY within
/// `reconstruction.py` itself, among each other -- NEITHER `startup.py`
/// NOR `streaming.py` (the two real, live production pipelines) ever call
/// `combine_multiscale_bands`. Both call `combine_recovered_candidate`
/// directly instead (confirmed the same way -- see that function's own
/// doc comment below). `combine_multiscale_bands`/`dead_zone_residual`/
/// `BandLimits` are ported and tested below (Group B2) per this plan's own
/// explicit request (Task 2's `<behavior>`/`must_haves.artifacts`), but
/// `select_feature_band_extrema` -- the one member of this cluster with
/// genuinely ZERO callers anywhere, including within
/// `combine_multiscale_bands` itself -- is skipped (same "orphaned legacy
/// code" category as Task 1's `pad_reconstruction_history`; not requested
/// by name in this plan's `<ground_truth_methodology>` or
/// `must_haves.artifacts`).
#[cfg(test)]
#[derive(Debug, Clone, Copy)]
struct BandLimits {
    minimum: [f32; 3],
    maximum: [f32; 3],
}

/// Ported from `dead_zone_residual`: remove an interval, retain only excess
/// change. `heal` itself never calls this (see the dead-code finding
/// above); ported and tested (Group B2) for plan-literal completeness.
#[cfg(test)]
fn dead_zone_residual(value: [f32; 3], minimum: [f32; 3], maximum: [f32; 3]) -> [f32; 3] {
    std::array::from_fn(|c| {
        if value[c] < minimum[c] {
            value[c] - minimum[c]
        } else if value[c] > maximum[c] {
            value[c] - maximum[c]
        } else {
            0.0
        }
    })
}

/// Ported from `combine_multiscale_bands`: `A + gated(B-A) + gated(C-B) +
/// gated(original-C)`, pure float32 throughout (no f64 widening anywhere
/// in the real source -- distinct from `combine_recovered_candidate`'s own
/// f64-widened accumulation below). See the dead-code finding above: this
/// is a documented alternate combiner `heal` does not call.
#[cfg(test)]
fn combine_multiscale_bands(
    candidate_a: [f32; 3],
    candidate_b: [f32; 3],
    candidate_c: [f32; 3],
    original: [f32; 3],
    limits_ab: &BandLimits,
    limits_bc: &BandLimits,
    limits_original_c: &BandLimits,
    weights: [f32; 3],
) -> [f32; 3] {
    let band_ab = dead_zone_residual(
        std::array::from_fn(|c| candidate_b[c] - candidate_a[c]),
        limits_ab.minimum,
        limits_ab.maximum,
    );
    let band_bc = dead_zone_residual(
        std::array::from_fn(|c| candidate_c[c] - candidate_b[c]),
        limits_bc.minimum,
        limits_bc.maximum,
    );
    let band_original = dead_zone_residual(
        std::array::from_fn(|c| original[c] - candidate_c[c]),
        limits_original_c.minimum,
        limits_original_c.maximum,
    );
    let mut result = candidate_a;
    for c in 0..3 {
        result[c] += band_ab[c] * weights[0];
        result[c] += band_bc[c] * weights[1];
        result[c] += band_original[c] * weights[2];
    }
    result
}

/// Ported from `FeatureBandExtremaMode`/`feature_band_extrema_mode`. Under
/// this port's fixed profile constants (`resolution_metric=4000`,
/// `cross_neighbor_cutoff=1_600`), `4000 > 1_600` is always true, so
/// `combine_recovered_candidate` always runs in `CrossNeighbor` mode --
/// `feature_records` always needs exactly 5 rows (current pixel + its 4
/// immediate neighbors). Computed via this function (not hardcoded)
/// anyway, for a faithful, general port that would still behave correctly
/// if the profile constants ever changed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FeatureBandExtremaMode {
    CenterOnly,
    CrossNeighbor,
}

fn feature_band_extrema_mode(resolution_metric: u32, cross_neighbor_cutoff: u32) -> FeatureBandExtremaMode {
    if resolution_metric > cross_neighbor_cutoff {
        FeatureBandExtremaMode::CrossNeighbor
    } else {
        FeatureBandExtremaMode::CenterOnly
    }
}

/// One scalar auxiliary-pyramid transition range. Ported from
/// `FeatureBandRange`.
#[derive(Debug, Clone, Copy)]
struct FeatureBandRange {
    minimum: f64,
    maximum: f64,
}

/// Ported from `feature_band_ranges`: build A21-A69, A16-A21, and A1-A16
/// scalar ranges. `feature_records[0]` must be the current pixel's own
/// record; in `CrossNeighbor` mode (always, under this port's fixed
/// profile -- see `feature_band_extrema_mode`), `feature_records` must
/// have exactly 5 rows: `[current, left, right, up, down]`, matching the
/// exact order verified directly against the real production call sites
/// (`startup.py`/`streaming.py`, both build their 5-row `features` array
/// in this identical `(center, x-1, x+1, y-1, y+1)` order).
fn feature_band_ranges(feature_records: &[[f32; 4]], mode: FeatureBandExtremaMode) -> [FeatureBandRange; 3] {
    let selected: &[[f32; 4]] = match mode {
        FeatureBandExtremaMode::CenterOnly => &feature_records[..1],
        FeatureBandExtremaMode::CrossNeighbor => feature_records,
    };
    std::array::from_fn(|transition| {
        let mut min_v = f64::INFINITY;
        let mut max_v = f64::NEG_INFINITY;
        for record in selected {
            let diff = record[transition + 1] as f64 - record[transition] as f64;
            min_v = min_v.min(diff);
            max_v = max_v.max(diff);
        }
        // Real source narrows to f32 (np.float32(np.min/max(...))) before
        // widening back for storage -- preserved exactly.
        FeatureBandRange { minimum: (min_v as f32) as f64, maximum: (max_v as f32) as f64 }
    })
}

/// Ported from `_automatic_strengths`. Returns `(mutated_weight_record,
/// strengths)` -- `mutated_weight_record` is exposed only for API parity
/// with the real source's own `CombinerResult.weights_after_automatic_strengths`
/// bookkeeping field; nothing downstream in `combine_recovered_candidate`
/// reads it back (confirmed by reading that function's own body directly),
/// so this port does not carry it forward into its own `CombinerResult`
/// equivalent below.
fn automatic_strengths(weight_record: [f32; 4], configured: [f32; 3]) -> [f64; 3] {
    let mut mutated = weight_record;
    let mut strengths = [0f64; 3];

    if configured[0] == 0.0 {
        let doubled = (2.0f64 * mutated[1] as f64) as f32;
        mutated[1] = doubled;
        let clamped = (mutated[1] as f64).max(0.0).min(1.0);
        mutated[1] = clamped as f32;
        strengths[0] = mutated[1] as f64;
    } else {
        strengths[0] = configured[0] as f64;
    }

    if configured[1] == 0.0 {
        if mutated[2] < 0.0 {
            mutated[2] = 0.0;
        }
        strengths[1] = mutated[2] as f64;
    } else {
        strengths[1] = configured[1] as f64;
    }

    if configured[2] == 0.0 {
        strengths[2] = (mutated[3] as f64) * (mutated[3] as f64);
    } else {
        strengths[2] = configured[2] as f64;
    }

    strengths
}

/// Ported from `asymmetric_dead_zone_residual`: Nikon's sign-aware
/// asymmetric dead zone, in widened f64 precision.
fn asymmetric_dead_zone_residual(
    value: [f64; 3],
    feature_range: FeatureBandRange,
    factors_a: [f32; 3],
    factors_b: [f32; 3],
) -> [f64; 3] {
    let edge_min = feature_range.minimum;
    let edge_max = feature_range.maximum;
    let (upper, lower): ([f64; 3], [f64; 3]) = if edge_min < 0.0 && edge_max < 0.0 {
        (std::array::from_fn(|c| factors_b[c] as f64 * edge_max), std::array::from_fn(|c| factors_a[c] as f64 * edge_min))
    } else {
        (std::array::from_fn(|c| factors_a[c] as f64 * edge_max), std::array::from_fn(|c| factors_b[c] as f64 * edge_min))
    };
    std::array::from_fn(|c| {
        if value[c] > upper[c] {
            value[c] - upper[c]
        } else if value[c] < lower[c] {
            value[c] - lower[c]
        } else {
            0.0
        }
    })
}

/// Receipt for one combined reconstruction candidate. Ported from
/// `CombinerResult`, minus `weights_after_automatic_strengths` (see
/// `automatic_strengths`'s own doc comment for why it is not carried
/// forward). `candidates_after_stages[0]` = initial (C69), `[1]` = after
/// coarse correction, `[2..5]` = after each of the 3 bands. `heal` (Task
/// 3) only reads `.candidate`; the other fields exist to satisfy this
/// plan's own `<ground_truth_methodology>` mandate to verify intermediate
/// stages, not just the end-to-end result (Group B) -- retained on the
/// struct (matching the real dataclass's own bookkeeping-field precedent,
/// e.g. `IceParameters.sample_threshold` from plan 16-01) rather than
/// discarded, so a future regression in an intermediate stage still fails
/// a targeted test instead of only the end-to-end one.
#[derive(Debug, Clone, Copy)]
struct CombinerResult {
    candidate: [f64; 3],
    #[allow(dead_code)]
    strengths: [f64; 3],
    #[allow(dead_code)]
    residuals: [[f64; 3]; 3],
    #[allow(dead_code)]
    candidates_after_stages: [[f64; 3]; 5],
    // Not read by `heal` -- `write_reconstructed_pixel` re-derives its own
    // equivalent validity check directly from `.candidate` (matching the
    // real source: startup.py/streaming.py never read `combined.valid`
    // either, confirmed via direct grep -- only `combined.candidate` feeds
    // `write_reconstructed_pixel`). Retained for the same
    // ground-truth-verification reason as the other diagnostic fields above.
    #[allow(dead_code)]
    valid: bool,
}

/// Ported from `combine_recovered_candidate`: Nikon's coarse correction
/// plus exact three-band writer algebra. Confirmed via direct grep as the
/// REAL, live path both `startup.py` and `streaming.py` call directly
/// (unlike `combine_multiscale_bands` above) -- this is the function
/// `heal` itself calls, consuming `IceParameters`'s own
/// `cross_neighbor_cutoff` through `dither_scales` fields (plan 16-01's
/// `ReconstructionParameters`-equivalent fields; no second parameters
/// struct, per this plan's own `<scope_map>`).
fn combine_recovered_candidate(
    candidate_69: [f32; 3],
    candidate_21: [f32; 3],
    candidate_16: [f32; 3],
    original: [f32; 3],
    weight_record: [f32; 4],
    feature_records: &[[f32; 4]],
    params: &IceParameters,
) -> CombinerResult {
    let mode = feature_band_extrema_mode(params.resolution_metric, params.cross_neighbor_cutoff);
    let ranges = feature_band_ranges(feature_records, mode);
    let strengths = automatic_strengths(weight_record, params.configured_strengths);

    let mut candidate: [f64; 3] = std::array::from_fn(|c| candidate_69[c] as f64);
    let mut stages = [[0f64; 3]; 5];
    stages[0] = candidate;

    if params.coarse_enabled {
        let coarse_delta = params.coarse_reference as f64 - feature_records[0][0] as f64;
        for c in 0..3 {
            candidate[c] += params.coarse_slopes[c] as f64 * coarse_delta;
        }
    }
    stages[1] = candidate;

    let mut residuals = [[0f64; 3]; 3];
    let pairs: [([f32; 3], [f32; 3]); 3] = [(candidate_69, candidate_21), (candidate_21, candidate_16), (candidate_16, original)];
    for band in 0..3 {
        if params.band_enabled[band] {
            let scale = params.band_scales[band] as f64;
            let (coarse, fine) = pairs[band];
            let difference: [f64; 3] = std::array::from_fn(|c| scale * (fine[c] as f64 - coarse[c] as f64));
            residuals[band] = asymmetric_dead_zone_residual(difference, ranges[band], params.factors_a[band], params.factors_b[band]);
            for c in 0..3 {
                candidate[c] += strengths[band] * residuals[band][c];
            }
        }
        stages[band + 2] = candidate;
    }

    let valid = candidate.iter().all(|v| v.is_finite() && *v > 0.0);
    CombinerResult { candidate, strengths, residuals, candidates_after_stages: stages, valid }
}

/// Ported from `driver_forces_fallback`: evaluate the recovered row gate
/// before reconstruction is entered. Under this port's fixed profile
/// constants (`row_reconstruction_gate=0`, `driver_gate_primary=true`,
/// `driver_gate_secondary=true`), this reduces to `weight_record[3] >=
/// 1.0` -- i.e. "the pixel's own raw (unrenormalized) continuous_score is
/// already at the clean ceiling" -- the SAME condition, verified directly
/// against `detect_defects`'s own renormalization formula, that makes
/// `DefectMap.score` read exactly `0.0` for that pixel. `heal` calls this
/// as an INNER safety net alongside its own outer `score != 0.0` gate (see
/// `heal`'s own doc comment, plan 16-02 Task 3) -- both gates agree by
/// construction under this port's fixed profile, but `heal` honors this
/// one directly rather than assuming that agreement, matching the real
/// production call sites (`startup.py`/`streaming.py`), which both call
/// this INSIDE their own per-pixel reconstruction attempt, not only via an
/// outer eligibility filter.
fn driver_forces_fallback(weight_record: [f32; 4], params: &IceParameters) -> bool {
    if params.row_reconstruction_gate != 0 {
        return true;
    }
    let floor_enabled = params.driver_gate_primary || params.driver_gate_secondary;
    floor_enabled && weight_record[3] >= 1.0
}

// --- LCG24 / DitherBounds / conditional_dither_delta (pulled forward from
// Task 3's own Group X -- see this section's SCOPE NOTE above) ---

const LCG24_MASK: u32 = 0x00FF_FFFF;
const NIKON_PE_INITIAL_STATE: u32 = 0x3045;
/// `float.fromhex("0x1.fffffep-25")` -- ICEDLL.dll VA 0x109ce5f8 stores
/// float32 bits 0x337fffff, the value immediately below exact 2**-24.
/// Rust has no hex-float literal syntax, so this is expressed via its
/// exact IEEE754 binary64 bit pattern (`0x3E6FFFFFE0000000`, verified via
/// a live `struct.unpack`/`float.fromhex` round trip during this plan's
/// execution) rather than an arithmetic approximation.
const NIKON_NORMALIZATION: f64 = f64::from_bits(0x3E6F_FFFF_E000_0000);

/// Ported from `rng.py`'s `LCG24`: the exact 24-bit state transition
/// recovered at preferred VA 0x1002f920. State is per-instance (mirroring
/// the real source's own "per job" design rationale) -- `heal` (Task 3)
/// owns exactly one `LCG24`, threaded mutably through its per-pixel writes
/// in raster order, matching the real streaming/startup pipelines' own
/// sequential per-pixel RNG consumption.
#[derive(Debug, Clone, Copy)]
struct Lcg24 {
    state: u32,
}

impl Lcg24 {
    fn from_nikon_pe_initial_state() -> Self {
        Lcg24 { state: NIKON_PE_INITIAL_STATE }
    }

    fn advance(&mut self) -> u32 {
        self.state = (125u32.wrapping_mul(self.state).wrapping_add(1)) & LCG24_MASK;
        self.state
    }

    fn centered_unit(&mut self) -> f64 {
        let state = self.advance();
        (state as f64 + 1.0) * NIKON_NORMALIZATION - 0.5
    }

    fn sample(&mut self, center: f64, span: f64) -> f64 {
        center + self.centered_unit() * span
    }
}

/// Ported from `dither.py`'s `DitherBounds` -- the bare 4-field dataclass
/// shape (low/high/low_index/high_index). This task defines the struct
/// (needed by `conditional_dither_delta`/`write_reconstructed_pixel`
/// below) but not its real constructor
/// (`percentile_bound_indices`/`DitherBounds::from_lookup`, which ties it
/// to the response LUT) -- that arrives in Task 3, per this section's
/// SCOPE NOTE above. This task's own tests construct it via a struct
/// literal using pre-verified real values instead.
#[derive(Debug, Clone, Copy)]
struct DitherBounds {
    low: f32,
    high: f32,
    #[allow(dead_code)] // carried for provenance parity with the real dataclass; not read by conditional_dither_delta itself
    low_index: usize,
    #[allow(dead_code)]
    high_index: usize,
}

/// Ported from `dither.py`'s `conditional_dither_delta`: Nikon's accepted
/// binary64-valued dither delta, or zero. The generator is called exactly
/// once only when `low < value < high`. Preserves the real source's own
/// two explicit binary64 temporaries and multiplication order EXACTLY
/// (`coefficient = 4.0 / (width * width); envelope = ((high - candidate) *
/// (candidate - low)) * coefficient`) -- the real source's own docstring
/// warns reassociating this changes low bits for real trace values even
/// though algebraically equivalent.
///
/// Precondition (structurally guaranteed by this port's only caller,
/// `write_reconstructed_pixel`, not re-checked here): `value` is finite --
/// `write_reconstructed_pixel` only ever calls this after its own
/// `valid = candidate.is_finite() && candidate > 0.0` gate already passed.
/// `bounds`/`scale` are always finite fixed profile constants. A
/// hypothetical non-finite `value` would still not panic here (Rust's
/// float comparisons return `false`, never panic, on NaN), it would simply
/// fall through to the `low < value < high` early-return.
fn conditional_dither_delta(value: f64, bounds: &DitherBounds, scale: f32, generator: &mut Lcg24) -> f64 {
    let candidate32 = value as f32;
    let low32 = bounds.low;
    let high32 = bounds.high;
    let candidate = candidate32 as f64;
    let low = low32 as f64;
    let high = high32 as f64;
    if !(low < high) {
        return 0.0;
    }
    if !(low < candidate && candidate < high) {
        return 0.0;
    }
    let width = high - low;
    let coefficient = 4.0 / (width * width);
    let envelope = ((high - candidate) * (candidate - low)) * coefficient;
    let random_span = (scale as f64 * candidate) as f32;
    let random_value = generator.sample(0.0, random_span as f64);
    let delta = envelope * random_value;
    let changed = candidate + delta;
    if low < changed && changed < high {
        delta
    } else {
        0.0
    }
}

/// Receipt for one final reconstructed-pixel write. Ported from
/// `WriterResult`, minus `dither_invocations`/`rng_advances` (pure
/// call-count bookkeeping `heal` does not need -- this port's own tests
/// verify RNG consumption by comparing `Lcg24.state` before/after instead,
/// which is an equally strong, simpler check). `heal` only reads
/// `.values`; `copied_original`/`valid_candidate` exist for this plan's
/// own Group F test assertions (proving WHICH path the writer took, not
/// just its numeric output), matching `CombinerResult`'s own
/// diagnostic-field precedent above.
#[derive(Debug, Clone, Copy)]
struct WriterResult {
    values: [f32; 3],
    #[allow(dead_code)]
    copied_original: [bool; 3],
    #[allow(dead_code)]
    valid_candidate: bool,
}

/// Ported from `write_reconstructed_pixel`: apply final validity,
/// original-floor, redraw, and float32-store rules. Confirmed via direct
/// reading of `streaming.py`/`startup.py`'s own call sites that dither is
/// applied INSIDE this function (per-channel, via `conditional_dither_delta`
/// directly) -- there is no separate external dither step applied to this
/// function's OUTPUT afterward (`reconstruction_dither_draws`, which
/// SOUNDS like it might be that step, has zero callers anywhere in the
/// real package outside its own definition -- see plan 16-02 Task 3's own
/// notes for that finding).
fn write_reconstructed_pixel(
    candidate: [f64; 3],
    original: [f32; 3],
    params: &IceParameters,
    dither_bounds: &DitherBounds,
    generator: &mut Lcg24,
) -> WriterResult {
    let valid = candidate.iter().all(|v| v.is_finite() && *v > 0.0);
    if !valid {
        return WriterResult { values: original, copied_original: [true; 3], valid_candidate: false };
    }

    let floor_enabled = params.driver_gate_primary || params.driver_gate_secondary;
    let mut output = [0f32; 3];
    let mut copied = [false; 3];
    for channel in 0..3 {
        let scale = params.dither_scales[channel];
        let first_delta = conditional_dither_delta(candidate[channel], dither_bounds, scale, generator);
        if floor_enabled && candidate[channel] + first_delta <= original[channel] as f64 {
            output[channel] = original[channel];
            copied[channel] = true;
        } else {
            let mut delta = first_delta;
            if floor_enabled {
                delta = conditional_dither_delta(candidate[channel], dither_bounds, scale, generator);
            }
            output[channel] = (candidate[channel] + delta) as f32;
        }
    }
    WriterResult { values: output, copied_original: copied, valid_candidate: true }
}

