/// Ported from `dither.py`'s `percentile_bound_indices`: Nikon's truncated
/// 1%/99% indices, each clamped to `maximum_index`. `maximum_index` is
/// always `65_535` in this port's own call site (`heal`, below) -- the
/// response LUT's own last valid index -- but implemented generally,
/// matching the real function's own domain (`0..=0xFFFF`).
fn percentile_bound_indices(maximum_index: u32) -> (usize, usize) {
    let n = maximum_index as f32;
    let low = (n * 0.01f32).trunc() as u32;
    let high = (n * 0.99f32).trunc() as u32;
    (low.min(maximum_index) as usize, high.min(maximum_index) as usize)
}

impl DitherBounds {
    /// Ported from `DitherBounds.from_lookup`: the real constructor,
    /// deferred here from Task 2 (which only needed the bare struct + a
    /// pre-verified literal instance -- see that task's own SCOPE NOTE).
    /// The real, live production call sites (`engine.py`/
    /// `metal_backend/process.py`/`cuda_backend/process.py`, all excluded
    /// scope) always pass the response LUT itself as `lookup` -- confirmed
    /// via direct grep (`DEFAULT_PROFILE.dither_bounds(response.table)`) --
    /// matching this port's own `heal` call site below.
    fn from_lookup(lookup: &[f32], maximum_index: u32) -> DitherBounds {
        let (low_index, high_index) = percentile_bound_indices(maximum_index);
        DitherBounds { low: lookup[low_index], high: lookup[high_index], low_index, high_index }
    }
}

/// Ported from `dither.py`'s `apply_conditional_dither`: narrow-then-widen
/// convenience wrapper around `conditional_dither_delta` that returns the
/// dithered VALUE (not just the delta). `heal` itself calls
/// `write_reconstructed_pixel` directly (which calls
/// `conditional_dither_delta` inline, per Task 2's own findings) rather
/// than this wrapper -- ported and tested (Group X) for a complete,
/// faithful port of dither.py's own public surface.
#[cfg(test)]
fn apply_conditional_dither(value: f64, bounds: &DitherBounds, scale: f32, generator: &mut Lcg24) -> f32 {
    let candidate = value as f32;
    let delta = conditional_dither_delta(candidate as f64, bounds, scale, generator);
    (candidate as f64 + delta) as f32
}

/// Ported from `output.py`'s `InverseResponseFactors`: the recovered
/// high/low-byte inverse-response factor tables. This port implements
/// ONLY the GENERATION FORMULA (`recovered_16bit`'s own arithmetic) --
/// the real source's `H_FACTOR_SHA256`/`L_FACTOR_SHA256`
/// hash-verify-and-fail-closed check is skipped per plan 16-01's
/// `<scope_map>` (that check proves byte-parity with Nikon's OWN specific
/// constants across platforms; this port's own correctness is verified
/// directly against a live invocation of the real function instead --
/// Group E1 below).
struct InverseResponseFactors {
    high: [u32; 256],
    low: [u32; 256],
}

impl InverseResponseFactors {
    fn recovered_16bit() -> InverseResponseFactors {
        let mut high = [0u32; 256];
        let mut low = [0u32; 256];
        let scale = 16.0 * (2.0f64).log10() / 65535.0;
        for i in 0..256usize {
            let domain = i as f64;
            high[i] = ((16.0 * (10.0f64).powf(256.0 * domain * scale)) + 0.5).floor() as u32;
            low[i] = ((65536.0 * (10.0f64).powf(domain * scale)) + 0.5).floor() as u32;
        }
        InverseResponseFactors { high, low }
    }
}

/// Ported from `output.py`'s `work_value_indices`: Nikon's finite-domain
/// half-up index conversion and clamp, specialized to one scalar sample
/// (the real function is NumPy-vectorized over a whole HxWx3 array; this
/// port applies the same per-sample arithmetic directly, since `heal`
/// processes one pixel at a time -- see this file's own established
/// per-pixel adaptation precedent from Task 1).
fn work_value_indices(work: f32) -> u16 {
    let widened = work as f64 + 0.5;
    let clamped = widened.max(0.0).min(65535.0);
    clamped.trunc() as u16
}

/// Ported from `output.py`'s `emit_public_rgb16`: convert one float32 work
/// RGB triplet to Nikon's public uint16 sample values via the
/// high/low-byte factor tables. `(high*low)>>20` is provably >= 1 for
/// every reachable `(high[i], low[j])` pair under `recovered_16bit`'s own
/// monotonically-increasing tables (the domain minimum, `i=j=0`, already
/// yields exactly `1`) -- `saturating_sub` is still used rather than a bare
/// `- 1` as defensive insurance against a hypothetical future profile
/// change, never observed to trigger, matching this module's established
/// "never panic on frame-or-parameter-derived floating point" precedent
/// (see `rail_excluded_mean`'s own `denom.max(1e-9)` guard, plan 16-01).
fn emit_public_rgb16_pixel(work_rgb: [f32; 3], factors: &InverseResponseFactors) -> [u16; 3] {
    std::array::from_fn(|c| {
        let index = work_value_indices(work_rgb[c]) as usize;
        let high = factors.high[index >> 8] as u64;
        let low = factors.low[index & 0xFF] as u64;
        ((high * low) >> 20).saturating_sub(1) as u16
    })
}

/// Repaired RGB (u16, matches `parity::image_io::Rgb16Image`'s pixel
/// convention) plus the `DefectMap` that produced it.
pub struct IceResult {
    pub repaired_rgb: Vec<[u16; 3]>,
    pub defect_map: DefectMap,
}

/// Returns the current pixel's own feature record if `(y, x)` falls inside
/// the frame, or the zero record otherwise. Extends `extract_scalar_patch_9x9`'s
/// own zero-padding philosophy (Task 1) to whole missing cross-neighbor
/// PIXELS, not just windowed-off cells within an otherwise-valid pixel's
/// own 9x9 neighborhood -- verified directly (Task 2's Group F3) that this
/// produces a finite, non-panicking `combine_recovered_candidate` result
/// even when 2 of 4 cross-neighbors are entirely missing (a frame corner).
fn feature_record_at_or_zero(
    score_plane: &[f32],
    auxiliary_plane: &[f32],
    weighted_auxiliary_plane: &[f32],
    width: usize,
    height: usize,
    y: i64,
    x: i64,
    fallback: f32,
) -> [f32; 4] {
    if y < 0 || y >= height as i64 || x < 0 || x >= width as i64 {
        return [0.0; 4];
    }
    let (_, record) = weight_and_auxiliary_record_for_pixel(
        score_plane,
        auxiliary_plane,
        weighted_auxiliary_plane,
        width,
        height,
        y as usize,
        x as usize,
        fallback,
    );
    record
}

/// Reconstructs only pixels where `defects.score[i] > 0.0`; every pixel
/// where `defects.score[i] == 0.0` appears UNCHANGED in the returned Vec
/// (bit-identical to `frame.rgb[i]`) -- this is the "grain-preserving,
/// never touch a clean pixel" property README.md's own "Repairing without
/// smearing the grain" section describes as the whole point of a
/// reflection/reconstruction-based heal versus a blur-everywhere
/// inpainter. Mirrored by `driver_forces_fallback` as an INNER safety net
/// for every nonzero-score pixel too (see that function's own doc
/// comment) -- both gates agree by construction under this port's fixed
/// profile, and either one alone is sufficient to guarantee this
/// property, but `heal` honors both, matching the real production call
/// sites' own structure (an outer eligibility filter AND an inner
/// per-pixel gate, not just one or the other).
///
/// Recomputes the raw (internal, unrenormalized) auxiliary/continuous-score
/// planes from `frame`+`params` directly, mirroring exactly what
/// `detect_defects` computes internally -- `heal`'s own frozen signature
/// (plan 16-02's `<interfaces>`) only receives the RENORMALIZED
/// `DefectMap`, not the raw internal score `detect_defects` used to derive
/// it, so recomputing here from `frame`+`params` is the correct, necessary
/// way to satisfy that fixed signature (not a deviation -- the interface
/// was fixed by the plan before this task began).
pub fn heal(frame: &IceInputFrame, defects: &DefectMap, params: &IceParameters) -> Vec<[u16; 3]> {
    let width = frame.width as usize;
    let height = frame.height as usize;
    let lut = generate_response_lut();

    let working_rgb: Vec<[f32; 3]> = frame
        .rgb
        .iter()
        .map(|px| [convert_response(px[0], &lut), convert_response(px[1], &lut), convert_response(px[2], &lut)])
        .collect();
    let working_r: Vec<f32> = frame.rgb.iter().map(|px| convert_response(px[0], &lut)).collect();
    let working_ir: Vec<f32> = frame.ir.iter().map(|&sample| convert_response(sample, &lut)).collect();

    let auxiliary = derive_auxiliary_plane(&working_r, &working_ir);
    let raw_score = continuous_score_plane(&auxiliary, width, height, params);
    let weighted_auxiliary: Vec<f32> = auxiliary.iter().zip(raw_score.iter()).map(|(&a, &s)| a * s).collect();
    let weighted_rgb: Vec<[f32; 3]> = working_rgb
        .iter()
        .zip(raw_score.iter())
        .map(|(&rgb, &s)| [rgb[0] * s, rgb[1] * s, rgb[2] * s])
        .collect();

    let dither_bounds = DitherBounds::from_lookup(&lut, 65_535);
    let mut generator = Lcg24::from_nikon_pe_initial_state();
    let factors = InverseResponseFactors::recovered_16bit();

    let mut output = frame.rgb.clone();
    for y in 0..height {
        for x in 0..width {
            let idx = y * width + x;
            // Safe against a hypothetical mismatched-size DefectMap (never
            // produced by this module's own detect_defects/repair_frame,
            // but heal is a pub fn a future caller could theoretically
            // call with an unrelated DefectMap) -- degrade to "treat as
            // clean, do not touch" rather than panicking on an
            // out-of-range index, matching this whole module's "never
            // touch a clean pixel" default.
            let score = defects.score.get(idx).copied().unwrap_or(0.0);
            if score == 0.0 {
                continue;
            }

            let (weight_record, current_feature) = weight_and_auxiliary_record_for_pixel(
                &raw_score,
                &auxiliary,
                &weighted_auxiliary,
                width,
                height,
                y,
                x,
                params.coarse_reference,
            );

            if driver_forces_fallback(weight_record, params) {
                continue;
            }

            let yi = y as i64;
            let xi = x as i64;
            let feature_records = [
                current_feature,
                feature_record_at_or_zero(&raw_score, &auxiliary, &weighted_auxiliary, width, height, yi, xi - 1, params.coarse_reference),
                feature_record_at_or_zero(&raw_score, &auxiliary, &weighted_auxiliary, width, height, yi, xi + 1, params.coarse_reference),
                feature_record_at_or_zero(&raw_score, &auxiliary, &weighted_auxiliary, width, height, yi - 1, xi, params.coarse_reference),
                feature_record_at_or_zero(&raw_score, &auxiliary, &weighted_auxiliary, width, height, yi + 1, xi, params.coarse_reference),
            ];

            let candidate_patch = extract_rgb_patch_9x9(&weighted_rgb, width, height, y, x);
            let normalizers = [weight_record[0], weight_record[1], weight_record[2]];
            let candidates = recovered_rgb_candidates(&candidate_patch, normalizers, NonpositiveNormalizerPolicy::UnnormalizedSum);

            let original = working_rgb[idx];
            let combined =
                combine_recovered_candidate(candidates[0].rgb, candidates[1].rgb, candidates[2].rgb, original, weight_record, &feature_records, params);

            let write_result = write_reconstructed_pixel(combined.candidate, original, params, &dither_bounds, &mut generator);

            output[idx] = emit_public_rgb16_pixel(write_result.values, &factors);
        }
    }
    output
}

/// Convenience entry point: `detect_defects` (plan 16-01) then `heal`
/// (this plan). The function plan 16-03's candidate renderer calls.
pub fn repair_frame(frame: &IceInputFrame, params: &IceParameters) -> IceResult {
    let defects = detect_defects(frame, params);
    let repaired_rgb = heal(frame, &defects, params);
    IceResult { repaired_rgb, defect_map: defects }
}

