    /// A 12x12 uniform-baseline frame with ONE isolated pixel's IR sample
    /// dropped far below the rest (row 6, col 6) -- large enough that
    /// `perpendicular_radius = 4`'s neighborhood scan around (6,6) never
    /// touches the frame edge and has zero other anomalous samples nearby.
    fn build_isolated_spike_12x12() -> IceInputFrame {
        let rgb = vec![[30_000u16, 30_000, 30_000]; 144];
        let mut ir = vec![45_000u16; 144];
        ir[6 * 12 + 6] = 5_000;
        IceInputFrame { width: 12, height: 12, rgb, ir }
    }

    // === Group D: detect_defects end-to-end ==============================

    #[test]
    fn group_d_detect_defects_elevates_injected_defect_and_reads_zero_elsewhere() {
        let frame = build_defect_injected_8x8();
        let params = IceParameters::for_main_scan(&frame);
        let map = detect_defects(&frame, &params);

        assert_eq!(map.width, 8);
        assert_eq!(map.height, 8);
        assert_eq!(map.score.len(), 64);

        // Verified during this plan's execution: continuous_score_plane's
        // own horizontal 3-tap minimum filter spreads the 2x2 raw injection
        // (rows 3-4, cols 3-4) into a 2x4 depressed-score region (rows 3-4,
        // cols 2-5) -- a real, faithful characteristic of the ported
        // algorithm (see continuous_score_plane's doc comment), not just
        // the original injection footprint. All 8 of these cells are
        // confirmed via genuine (unfiltered) corroboration from each other.
        let elevated: [(usize, usize); 8] =
            [(3, 2), (3, 3), (3, 4), (3, 5), (4, 2), (4, 3), (4, 4), (4, 5)];
        for (y, x) in elevated {
            let idx = y * 8 + x;
            assert!(
                map.score[idx] > 0.9,
                "elevated pixel ({y},{x}) expected severe score, got {}",
                map.score[idx]
            );
        }
        for y in 0..8usize {
            for x in 0..8usize {
                if elevated.contains(&(y, x)) {
                    continue;
                }
                let idx = y * 8 + x;
                assert_eq!(
                    map.score[idx], 0.0,
                    "clean pixel ({y},{x}) expected exactly 0.0, got {}",
                    map.score[idx]
                );
            }
        }
    }

    // === Group N: isolated single-pixel noise rejection ==================

    #[test]
    fn group_n_isolated_single_pixel_spike_rejected_as_unconfirmed_noise() {
        let frame = build_isolated_spike_12x12();
        let params = IceParameters::for_main_scan(&frame);
        let width = 12usize;
        let height = 12usize;
        let spike_idx = 6 * width + 6;

        // Raw (pre-confirmation) score at the spike must be nonzero/severe
        // -- proves the confirmation step below actually does something,
        // not a no-op.
        let lut = generate_response_lut();
        let working_r: Vec<f32> = frame.rgb.iter().map(|px| convert_response(px[0], &lut)).collect();
        let working_ir: Vec<f32> = frame.ir.iter().map(|&s| convert_response(s, &lut)).collect();
        let auxiliary = derive_auxiliary_plane(&working_r, &working_ir);
        let raw_score = continuous_score_plane(&auxiliary, width, height, &params);
        let denom = (1.0f32 - params.floor).max(1e-9);
        let pre_confirmation = ((1.0 - raw_score[spike_idx]) / denom).clamp(0.0, 1.0);
        assert!(
            pre_confirmation > 0.9,
            "raw (pre-confirmation) score at the spike must be severe, got {pre_confirmation}"
        );

        // Post-confirmation: detect_defects must reject the isolated
        // spike's OWN location -- its neighbors, checked via UNFILTERED
        // auxiliary, are all genuinely clean, so is_confirmed finds zero
        // corroboration there.
        let map = detect_defects(&frame, &params);
        assert_eq!(
            map.score[spike_idx], 0.0,
            "isolated single-pixel spike must be rejected as unconfirmed noise, got {}",
            map.score[spike_idx]
        );

        // A pixel far from the spike (unaffected by either the raw anomaly
        // or continuous_score_plane's own horizontal smear) must read
        // exactly 0.0.
        assert_eq!(map.score[0], 0.0, "far clean pixel (0,0) expected exactly 0.0");
        assert_eq!(
            map.score[(height - 1) * width + (width - 1)],
            0.0,
            "far clean pixel (bottom-right corner) expected exactly 0.0"
        );

        // The immediate left/right row-neighbors of the spike (row 6, cols
        // 5 and 7) DO read elevated: continuous_score_plane's own
        // horizontal smear genuinely depresses their FILTERED score, and
        // is_confirmed correctly finds the genuine spike at (6,6) as real
        // corroboration within perpendicular_radius -- the confirmed-defect
        // footprint tracking the algorithm's own real smear, not a
        // rejection-logic bug. Verified this is NOT universal: pixels
        // further away stay exactly 0.0, checked via the two far-corner
        // assertions above and the full-grid scan below.
        assert!(
            map.score[6 * width + 5] > 0.9,
            "smeared neighbor (6,5) expected elevated (confirmed via the genuine spike)"
        );
        assert!(
            map.score[6 * width + 7] > 0.9,
            "smeared neighbor (6,7) expected elevated (confirmed via the genuine spike)"
        );

        // Every pixel outside {(6,5),(6,6),(6,7)} must read exactly 0.0.
        for y in 0..height {
            for x in 0..width {
                if y == 6 && (5..=7).contains(&x) {
                    continue;
                }
                let idx = y * width + x;
                assert_eq!(
                    map.score[idx], 0.0,
                    "clean pixel ({y},{x}) expected exactly 0.0, got {}",
                    map.score[idx]
                );
            }
        }
    }

