    // === Group C: multiscale candidate generation (plan 16-02, Task 1) ===

    /// Matches this plan's own suggested deterministic 9x9 formula exactly
    /// (`<action>`: `v[y][x] = 0.05 + 0.9 * ((y*9+x)*37 % 97) / 97.0`).
    fn hand_built_9x9_scalar_patch() -> [[f32; 9]; 9] {
        std::array::from_fn(|y| {
            std::array::from_fn(|x| 0.05f32 + 0.9f32 * (((y * 9 + x) as u32 * 37 % 97) as f32) / 97.0f32)
        })
    }

    fn hand_built_9x9_rgb_pattern() -> [[[f32; 3]; 9]; 9] {
        std::array::from_fn(|y| {
            std::array::from_fn(|x| {
                [
                    0.1f32 + 0.01 * y as f32 + 0.02 * x as f32,
                    0.2f32 + 0.015 * y as f32 + 0.01 * x as f32,
                    0.3f32 + 0.005 * y as f32 + 0.03 * x as f32,
                ]
            })
        })
    }

