    /// 13x13 synthetic score/auxiliary/weighted-rgb planes, matching this
    /// plan's own Group W ground-truth fixture exactly (deterministic,
    /// arbitrary-but-plausible magnitudes: score in continuous_score's real
    /// `[floor, 1.0]` range, auxiliary/rgb in the tens-of-thousands range
    /// matching real response-converted working values).
    fn synthetic_score_aux_rgb_13x13() -> (Vec<f32>, Vec<f32>, Vec<[f32; 3]>) {
        let h = 13usize;
        let w = 13usize;
        let mut score = vec![0f32; h * w];
        let mut aux = vec![0f32; h * w];
        let mut rgb = vec![[0f32; 3]; h * w];
        for y in 0..h {
            for x in 0..w {
                let idx = y * w + x;
                score[idx] = 0.02 + 0.9 * (((y * 13 + x) as u32 * 53 % 101) as f32) / 101.0;
                aux[idx] = 40_000.0 + 1_000.0 * y as f32 - 700.0 * x as f32
                    + 13.0 * (((y * 7 + x * 3) % 11) as f32);
                rgb[idx] = [
                    10_000.0 + 50.0 * y as f32 + 30.0 * x as f32,
                    15_000.0 + 40.0 * y as f32 + 20.0 * x as f32,
                    20_000.0 + 30.0 * y as f32 + 45.0 * x as f32,
                ];
            }
        }
        (score, aux, rgb)
    }

