    #[test]
    fn group_w_degenerate_recovered_rgb_candidates_nonpositive_normalizer_policies() {
        let (score, aux, rgb) = synthetic_score_aux_rgb_13x13();
        let _ = aux;
        let width = 13usize;
        let height = 13usize;
        let weighted_rgb: Vec<[f32; 3]> = score
            .iter()
            .zip(rgb.iter())
            .map(|(&s, &c)| [s * c[0], s * c[1], s * c[2]])
            .collect();
        let patch = extract_rgb_patch_9x9(&weighted_rgb, width, height, 6, 6);
        let zero_norm = [0.0f32, 0.0f32, 5.0f32];

        // Ground truth: a live invocation of the real recovered_rgb_candidates
        // with this identical patch and normalizer triple, under both
        // policies, during this plan's execution.
        const EPS: f64 = 2e-2;
        let unnorm = recovered_rgb_candidates(&patch, zero_norm, NonpositiveNormalizerPolicy::UnnormalizedSum);
        let expected_unnorm: [[f64; 3]; 3] = [
            [4782.9765625, 7011.2021484375, 9333.150390625],
            [4997.78662109375, 7325.64697265625, 9754.9404296875],
            [899.127685546875, 1317.5369873046875, 1754.0333251953125],
        ];
        for i in 0..3 {
            assert!(unnorm[i].valid, "UNNORMALIZED_SUM candidate[{i}] expected valid");
            for c in 0..3 {
                assert_close(unnorm[i].rgb[c] as f64, expected_unnorm[i][c], EPS, &format!("unnorm[{i}][{c}]"));
            }
        }

        let invalid = recovered_rgb_candidates(&patch, zero_norm, NonpositiveNormalizerPolicy::Invalid);
        // metric 0,1 (zero normalizer): INVALID policy -> zeroed, invalid.
        assert_eq!(invalid[0].rgb, [0.0, 0.0, 0.0]);
        assert!(!invalid[0].valid);
        assert_eq!(invalid[1].rgb, [0.0, 0.0, 0.0]);
        assert!(!invalid[1].valid);
        // metric 2 (positive normalizer): unaffected by policy, still a
        // normal division, still valid.
        assert!(invalid[2].valid, "positive-normalizer candidate must stay valid under INVALID policy too");
        for c in 0..3 {
            assert_close(invalid[2].rgb[c] as f64, expected_unnorm[2][c], EPS, &format!("invalid[2][{c}]"));
        }
    }

