        // during this plan's execution, hand-picked so all 3 channels sit
        // INSIDE dither_bounds (real RNG-consuming dither), and channel 2
        // additionally exercises the floor-triggers-copy-original path
        // (candidate 44000.0 <= original 45000.0 after its first dither draw).
        let candidate = [50000.0, 44999.0, 44000.0];
        let original = [45000.0f32, 45000.0, 45000.0];
        let result = write_reconstructed_pixel(candidate, original, &params, &bounds, &mut gen);

