    #[test]
    fn group_x4_conditional_dither_delta_and_apply_match_real_python() {
        let bounds = real_dither_bounds();

        // Outside bounds (below low, above high): exactly 0.0, no RNG draw.
        let mut gen_below = Lcg24::from_nikon_pe_initial_state();
        let state_before = gen_below.state;
        assert_eq!(conditional_dither_delta(1000.0, &bounds, 0.01, &mut gen_below), 0.0);
        assert_eq!(gen_below.state, state_before, "below-bounds delta must not advance the RNG");

        let mut gen_above = Lcg24::from_nikon_pe_initial_state();
        let state_before2 = gen_above.state;
        assert_eq!(conditional_dither_delta(70000.0, &bounds, 0.01, &mut gen_above), 0.0);
        assert_eq!(gen_above.state, state_before2, "above-bounds delta must not advance the RNG");

        // Inside bounds: nonzero, bounded delta, matching a live Python
        // invocation on this identical literal input during this plan's
        // execution.
        let mut gen_inside = Lcg24::from_nikon_pe_initial_state();
        let delta = conditional_dither_delta(50000.0, &bounds, 0.01, &mut gen_inside);
        assert_close(delta, -199.96281903352815, 1e-6, "inside-bounds delta");
        assert_ne!(delta, 0.0);
        assert_ne!(gen_inside.state, 0x3045, "inside-bounds delta must advance the RNG");

        let mut gen_apply = Lcg24::from_nikon_pe_initial_state();
        let applied = apply_conditional_dither(50000.0, &bounds, 0.01, &mut gen_apply);
        assert_close(applied as f64, 49800.0390625, 1e-3, "apply_conditional_dither");
    }

