    // === Group R: heal + repair_frame end-to-end (plan 16-02, Task 3) =====

    #[test]
    fn group_r_heal_leaves_clean_pixels_untouched_and_changes_confirmed_defects() {
        let frame = build_defect_injected_8x8();
        let params = IceParameters::for_main_scan(&frame);
        let defects = detect_defects(&frame, &params);
        let repaired = heal(&frame, &defects, &params);

        assert_eq!(repaired.len(), frame.rgb.len());
        let mut any_changed = false;
        for i in 0..repaired.len() {
            if defects.score[i] == 0.0 {
                assert_eq!(repaired[i], frame.rgb[i], "zero-score pixel {i} must be bit-identical to the input");
            } else if repaired[i] != frame.rgb[i] {
                any_changed = true;
            }
        }
        assert!(any_changed, "at least one confirmed-defect pixel must have actually changed");
    }

    #[test]
    fn group_r_repair_frame_matches_calling_detect_defects_and_heal_directly() {
        let frame = build_defect_injected_8x8();
        let params = IceParameters::for_main_scan(&frame);

        let result = repair_frame(&frame, &params);
        let direct_defects = detect_defects(&frame, &params);
        let direct_repaired = heal(&frame, &direct_defects, &params);

        assert_eq!(result.defect_map, direct_defects, "repair_frame's defect_map must match calling detect_defects directly");
        assert_eq!(result.repaired_rgb, direct_repaired, "repair_frame's repaired_rgb must match calling heal directly with that same defect_map");
    }

    /// Plan 16-02's own `<verification>` item 3, satisfied directly on
    /// `repair_frame`'s own output (not merely inferred by equivalence to
    /// the composed `detect_defects`+`heal` calls above): a synthetic
    /// clean-plus-defect frame leaves clean pixels untouched and changes
    /// defect pixels, end to end through the single public entry point
    /// plan 16-03's candidate renderer will actually call.
    #[test]
    fn group_r_repair_frame_leaves_clean_pixels_untouched_and_changes_defect_pixels() {
        let frame = build_defect_injected_8x8();
        let params = IceParameters::for_main_scan(&frame);
        let result = repair_frame(&frame, &params);

        assert_eq!(result.repaired_rgb.len(), frame.rgb.len());
        assert_eq!(result.defect_map.score.len(), frame.rgb.len());
        let mut any_changed = false;
        for i in 0..result.repaired_rgb.len() {
            if result.defect_map.score[i] == 0.0 {
                assert_eq!(result.repaired_rgb[i], frame.rgb[i], "clean pixel {i} must be bit-identical to the input");
            } else if result.repaired_rgb[i] != frame.rgb[i] {
                any_changed = true;
            }
        }
        assert!(any_changed, "at least one confirmed-defect pixel must have actually changed");
    }

    #[test]
    fn group_r_heal_does_not_panic_on_a_frame_smaller_than_the_9x9_neighborhood() {
        // A 3x3 frame -- every pixel's 9x9 neighborhood extract runs off
        // every side; every cross-neighbor lookup for a corner or edge
        // pixel is at least partially out of frame. Exercises the same
        // zero-padding convention as Group F3, on the smallest frame this
        // module's own neighborhood math can meaningfully be asked about.
        let mut frame = synthetic_rgbi(3, 3, 0);
        frame.ir[4] = 500; // center pixel: severe IR dip
        let params = IceParameters::for_main_scan(&frame);
        let result = repair_frame(&frame, &params);
        // Reaching this assertion at all is the real proof (no panic on a
        // frame smaller than the 9x9 neighborhood radius) -- `u16` is
        // range-safe by construction, so the meaningful checks left are
        // shape and non-mutation.
        assert_eq!(result.repaired_rgb.len(), 9);
        assert_eq!(result.defect_map.score.len(), 9);
    }

    #[test]
    fn group_r_heal_does_not_mutate_input_frame() {
        let frame = build_defect_injected_8x8();
        let before = frame.clone();
        let params = IceParameters::for_main_scan(&frame);
        let defects = detect_defects(&frame, &params);
        let _repaired = heal(&frame, &defects, &params);
        assert_eq!(frame, before, "heal must not mutate its input frame");
    }
